/* Forecast views share the current project. */
const PRE_REASONS={scored:'Оцінено',legal_review:'Правова перевірка',zero_basis:'Нульова база',history_unknown:'Повнота історії невідома',history_too_short:'Історія закоротка'};
const PRE_LABELS={log_basis:'Сума бази оцінки',log_dpd:'Давність прострочення',log_count_30:'Платежі за 30 днів',log_count_90:'Платежі за 90 днів',log_count_180:'Платежі за 180 днів',paid_fraction_90:'Сума платежів за 90 днів / база',paid_fraction_previous90:'Попередні 90 днів / база',days_since_payment_180:'Днів після останнього платежу',no_payment_180:'Відсутність платежів за 180 днів',segment_bank_early:'Сегмент: банк, рання прострочка',segment_bank_late:'Сегмент: банк, пізня прострочка',segment_mfo_early:'Сегмент: МФО, рання прострочка',segment_mfo_late:'Сегмент: МФО, пізня прострочка'};
const preState={loading:false,loaded:false,model:null,validation:null,original:null,case:null,result:null,view:'forecast',filter:'scored',search:'',selected:null,external:false};
async function renderPrepurchase(){
  if(!preState.loaded){
    $('#tab-prepurchase').innerHTML='<div class="panel loadscreen">Завантаження моделі та історії до покупки…</div>';$('#report-button').disabled=true;
    if(preState.loading)return;preState.loading=true;
    try{
      const paths=['prepurchase-model.json','prepurchase-validation.json','prepurchase-case.json'];
      const data=await Promise.all(paths.map(async p=>{const r=await fetch(p);if(!r.ok)throw Error('Не вдалося завантажити '+p);return r.json();}));
      [preState.model,preState.validation,preState.original]=data;preState.case=preState.original;
      preState.result=PRE.scorePackage(preState.model,preState.case);preState.loaded=true;
    }catch(err){preState.loading=false;$('#tab-prepurchase').innerHTML=`<div class="error">${esc(err.message)}</div>`;return;}
    preState.loading=false;if(active!=='prepurchase')return;
  }
  $('#report-button').disabled=false;updateSource();
  const p=preState.result,m=preState.model;
  $('#tab-prepurchase').innerHTML=`<div class="notice pre-warning"><b>Навчання на синтетичній історії.</b> Результати демонструють процес навчання і прогнозу; метрики не доводять точність для реальних українських портфелів. ${preState.external&&preState.view!=='comparison'?'Завантажені зовнішні дані оцінюються базовою демонстраційною моделлю. Для інвестиційного рішення її потрібно перенавчити та перевірити.':''}</div><div class="pre-tabs"><button data-pre-view="forecast" class="${preState.view==='forecast'?'selected':''}">Прогноз пакета</button><button data-pre-view="comparison" class="${preState.view==='comparison'?'selected':''}">Порівняння моделей · NN</button><button data-pre-view="validation" class="${preState.view==='validation'?'selected':''}">Перевірка базової моделі</button><button data-pre-view="data" class="${preState.view==='data'?'selected':''}">Дані та процес</button><span class="pre-model-id">${preState.view==='comparison'?'ФІКСОВАНИЙ ЕКСПЕРИМЕНТ':esc(m.model_id)}</span></div><div id="pre-body"></div>`;
  if(preState.view==='forecast')renderPreForecast();else if(preState.view==='comparison')renderModelComparison();else if(preState.view==='validation')renderPreValidation();else renderPreData();
}
function preMetricValue(x){return num(x/1e6,2)+' <em>млн ₴</em>';}
function renderPreForecast(){
  const r=preState.result,known=r.scores.filter(s=>s.status==='scored');
  const reasons={};r.scores.filter(s=>s.status!=='scored').forEach(s=>reasons[s.status]=(reasons[s.status]||0)+1);
  $('#pre-body').innerHTML=`<div class="metrics">${metric('Розраховано оцінки',num(r.scored)+' <em>/ '+num(r.total)+'</em>','Договорів із достатніми даними','emphasis')}${metric('Очікувані платні договори','≈ '+num(r.expected_payers),'Хоча б один платіж за 12 місяців')}${metric('Очікувані надходження',preMetricValue(r.expected_gross),'Валові збори за 12 місяців')}${metric('Потребують перевірки',num(r.total-r.scored),'Не прирівнюються до неплатників')}</div><div class="panel pre-summary"><div><h2>Прогноз із відомостей, доступних до угоди</h2><p>Дата зрізу — у кожному записі. Дані платежів після зрізу та записи, отримані пізніше, не впливають на оцінку.</p><p class="fine">${Object.entries(reasons).map(([k,n])=>esc(PRE_REASONS[k])+': '+num(n)).join(' · ')}${known.some(s=>s.unseen_seller)?' · Є новий для навчання продавець: потрібна додаткова перевірка.':''}</p></div><div class="download-links"><button class="button secondary" data-action="pre-import">↑ Пакет JSON</button><button class="button primary" data-action="pre-export">↓ Прогноз CSV</button>${preState.external?'<button class="button secondary" data-action="pre-reset">↺ Демо</button>':''}</div></div><div class="panel table-panel" style="margin-top:19px"><div class="panel-heading"><div><h2>Рейтинг очікуваних надходжень</h2><p>Без віднімання витрат. Ймовірність не означає гарантований платіж або гарантовану відсутність платежів.</p></div><span class="chip">Горизонт: 12 місяців</span></div><div class="toolbar"><input id="pre-search" type="search" aria-label="Пошук у прогнозі" placeholder="ID договору" value="${esc(preState.search)}"><select id="pre-filter" aria-label="Статус прогнозу"><option value="scored" ${preState.filter==='scored'?'selected':''}>Оцінені договори</option><option value="review" ${preState.filter==='review'?'selected':''}>Без прогнозу — перевірка</option><option value="all" ${preState.filter==='all'?'selected':''}>Усі договори</option></select></div><div class="table-wrap"><table><thead><tr><th>Договір</th><th>Сегмент</th><th class="num">P(платіж за 12 міс.)</th><th class="num">Сума при платежі</th><th class="num">Очікувана сума</th><th>Статус / пояснення</th></tr></thead><tbody id="pre-rows"></tbody></table></div><div class="pager"><span id="pre-row-count"></span><span>Показано до 30 записів</span></div></div><div class="notice" style="margin-top:19px">Прогноз поточного проєкту використовується в оцінці та симуляції.</div>`;
  renderPreRows();
}
function renderPreRows(){
  const a=preState.result.scores.filter(s=>(preState.filter==='all'||(preState.filter==='scored'?s.status==='scored':s.status!=='scored'))&&(!preState.search||s.loan_id.toLowerCase().includes(preState.search.toLowerCase()))).sort((x,y)=>(y.expected??-1)-(x.expected??-1));
  $('#pre-rows').innerHTML=a.length?a.slice(0,30).map(s=>`<tr><td><b>${esc(s.loan_id)}</b><br><small style="color:#8a9b8c">${esc(s.as_of_date)}</small></td><td>${NPL.SEGMENTS[s.segment].label}</td><td class="num">${s.probability===null?'—':pct(s.probability)}</td><td class="num">${s.conditional===null?'—':money(s.conditional)}</td><td class="num">${s.expected===null?'—':money(s.expected)}</td><td>${s.status==='scored'?`<button class="text-button" data-pre-loan="${esc(s.loan_id)}">Фактори оцінки →</button>`:`<span class="badge review">${esc(PRE_REASONS[s.status])}</span>`}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">За цими умовами записів немає.</td></tr>';
  $('#pre-row-count').textContent=num(a.length)+' договорів';
}
function renderPreValidation(){
  const v=preState.validation,m=v.metrics;
  $('#pre-body').innerHTML=`<div class="notice"><b>Лише синтетичний тест.</b> Наступні результати виміряні на згенерованих даних. AUC не є відсотком точних передбачень. Висока якість на такому тесті не означає готовності до реальних покупок.</div><div class="metrics">${metric('AUC на пізнішому тесті',num(m.auc,3),'Здатність ранжувати; не «точність, %»','emphasis')}${metric('Brier: помилка ймовірностей',num(m.brier,3),'Сегментний орієнтир: '+num(m.baseline_brier,3)+'; менше — краще')}${metric('Помилка загальної суми',(m.gross_error_fraction>=0?'+':'−')+num(Math.abs(m.gross_error_fraction)*100,1)+'<em> %</em>','Прогноз проти синтетичного факту')}${metric('MAE суми на договір',num(m.mae_money)+'<em> ₴</em>','Сегментний орієнтир: '+money(m.baseline_mae_money))}</div><div class="panel"><h2>Хронологія перевірки</h2><div class="pre-timeline"><div><span>01 · НАВЧАННЯ</span><strong>Зрізи I кв. 2023</strong><p>${num(v.counts.train)} договорів</p><small>Результати відомі до ${v.cutoffs.train_labels_known_before}</small></div><div><span>02 · КАЛІБРУВАННЯ</span><strong>Зрізи II кв. 2024</strong><p>${num(v.counts.calibration)} договорів</p><small>Результати відомі до ${v.cutoffs.calibration_labels_known_before}</small></div><div><span>03 · НЕЗАЛЕЖНИЙ ТЕСТ</span><strong>Зрізи III кв. 2025</strong><p>${num(v.counts.test)} договорів</p><small>Повні 12-місячні результати до осені 2026</small></div></div><p class="fine">Виключено через неповне спостереження: ${num(v.excluded.incomplete_outcome||0)}. Прибрано перетини за позичальниками між вибірками: ${num(v.counts.purged_borrowers)} записів. Портфелі мають єдину дату зрізу й не діляться випадково між періодами.</p></div><div class="two-col" style="margin-top:19px"><div class="panel"><h2>Чи відповідають ймовірності частотам</h2><p class="fine">10 рівних за кількістю груп тесту, від нижчих оцінок до вищих.</p><table><thead><tr><th>Група</th><th class="num">Кількість</th><th class="num">Середня P</th><th class="num">Факт платежу</th></tr></thead><tbody>${v.calibration_bins.map((b,i)=>`<tr><td>${i+1}</td><td class="num">${b.count}</td><td class="num">${pct(b.predicted)}</td><td class="num">${pct(b.observed)}</td></tr>`).join('')}</tbody></table></div><div class="panel"><h2>Ранжування та грошовий результат</h2><table><tbody><tr><td>Платні договори: прогноз / факт</td><td class="num">${num(m.expected_payers,1)} / ${num(m.actual_payers)}</td></tr><tr><td>Збори: прогноз</td><td class="num">${money(m.predicted_gross)}</td></tr><tr><td>Збори: синтетичний факт</td><td class="num">${money(m.actual_gross)}</td></tr><tr><td>Частка платників у всьому тесті</td><td class="num">${pct(m.overall_payer_share)}</td></tr><tr><td>Частка платників у верхніх 20% за P</td><td class="num">${pct(m.top20_payer_share)}</td></tr><tr><td>Частка зборів у цих верхніх 20%</td><td class="num">${pct(m.top20_cash_capture)}</td></tr></tbody></table><p class="fine">Орієнтир — частки платників і середні суми за сегментами, обчислені тільки на навчанні. Рейтинг не доводить, що конкретна дія стягнення збільшить платежі: для цього потрібен окремий аналіз впливу дій.</p></div></div>`;
}
function renderPreData(){
  $('#pre-body').innerHTML=`<div class="two-col"><div class="panel method-block"><h2>Три таблиці в одному JSON-пакеті</h2><ol><li><b>snapshots:</b> один зріз на договір: ID договору, позичальника, портфеля й продавця; as_of_date; issued_at; склад боргу; DPD; сегмент; якість; history_complete; history_start_date.</li><li><b>payments:</b> loan_id, payment_date, available_at, amount. Дата події та дата, коли про неї стало відомо, зберігаються окремо.</li><li><b>observations:</b> для навчання: loan_id, observed_until, available_at, complete. Дозволяє відрізняти нульові платежі від неповного спостереження.</li></ol><p>Для прогнозу потрібні лише snapshots і payments. Відсутність платежів стає ознакою тільки при явно підтвердженій повноті історії. Записи після зрізу не використовуються.</p><div class="download-links"><a class="button secondary" href="prepurchase-case.json" download>↓ Приклад до покупки</a><a class="button secondary" href="prepurchase-history.json" download>↓ Навчальна історія</a></div></div><div class="panel method-block"><h2>Від даних до оцінки</h2><ol><li>Звірити договори, платежі, дати доступності та повноту даних.</li><li>Розрахувати ознаки тільки до зрізу: платежі за 30/90/180 днів, давність останнього, частки сплаченого, суму і сегмент.</li><li>За повною наступною історією побудувати цілі за 12 календарних місяців.</li><li>Навчити й відкалібрувати модель на різних часових групах; перевірити на ще пізнішій.</li><li>Зафіксувати модель і застосувати до нового реєстру без майбутніх результатів.</li></ol><p>Базова реалізація: Logistic Regression → окреме сигмоїдальне калібрування; Ridge для суми погашення при платежі. Масштабування ознак навчається тільки на першій вибірці.</p><div class="download-links"><a class="button secondary" href="demo-source.zip" download>↓ Python, тести та схема</a><button class="button secondary" data-action="pre-import">↑ Свій JSON-пакет</button></div></div></div><div class="notice" style="margin-top:19px">Поточна модель навчена на синтетичних даних. Завантаження іншого реєстру не перенавчає її. Реальне навчання запускається Python-командою з дозволеною історією роботодавця; після незалежної перевірки можна замінити модель. Імпорт тут обробляється локально в пам’яті браузера.</div>`;
}
function showPreLoan(id){
  const s=preState.result.scores.find(s=>s.loan_id===id);if(!s||s.status!=='scored')return;
  const features=preState.model.features;
  const factors=(s.effects||[]).map((v,i)=>({value:v,key:features[i]})).sort((a,b)=>Math.abs(b.value)-Math.abs(a.value)).slice(0,4);
  $('#report-content').innerHTML=`<article class="memo"><div class="memo-label">СИНТЕТИЧНО НАВЧЕНА МОДЕЛЬ · ПОЯСНЕННЯ ОЦІНКИ</div><h2>${esc(id)}</h2><p>Зріз ${esc(s.as_of_date)}; прогноз до ${esc(s.horizon_end)}.</p><table><tbody><tr><td>Ймовірність хоча б одного платежу</td><td class="num">${pct(s.probability)}</td></tr><tr><td>Прогноз суми при платежі</td><td class="num">${money(s.conditional)}</td></tr><tr><td>Очікувана сума</td><td class="num">${money(s.expected)}</td></tr><tr><td>Відомі платежі за 90 днів</td><td class="num">${num(Math.expm1(s.features[3]))}</td></tr><tr><td>Останній платіж у 180-денному вікні</td><td class="num">${s.features[8]?'Не було':num(s.features[7]*180)+' днів тому'}</td></tr></tbody></table><h3>Найбільші внески у логарифм шансів відносно середнього навчання</h3><ul>${factors.map(f=>`<li>${esc(PRE_LABELS[f.key])}: ${f.value>=0?'позитивний':'негативний'} внесок (${num(f.value,2)}).</li>`).join('')}</ul><p>Це статистичні зв’язки всередині моделі, а не причини поведінки чи рекомендація конкретної дії. Майбутні платежі не використані для побудови ознак.</p></article>`;
  $('#report-dialog .dialog-actions').hidden=true;$('#report-dialog').showModal();
}
function prepurchaseMemo(){
  if(preState.view==='comparison')return comparisonMemo();
  if(!preState.loaded)return '<article class="memo"><p>Спочатку завантажте прогноз до покупки.</p></article>';
  const r=preState.result;
  return `<article class="memo"><div class="memo-label">ДО ПОКУПКИ · МОДЕЛЬ НАВЧЕНА НА СИНТЕТИЧНИХ ДАНИХ</div><h2>12-місячний прогноз надходжень</h2><p>Модель ${esc(r.model_id)}. Одиниця аналізу — договір.</p><table><tbody><tr><td>Договорів у пакеті</td><td class="num">${num(r.total)}</td></tr><tr><td>Оцінено / без прогнозу</td><td class="num">${num(r.scored)} / ${num(r.total-r.scored)}</td></tr><tr><td>Очікувані договори з платежами</td><td class="num">${num(r.expected_payers,1)}</td></tr><tr><td>Очікувані валові надходження за 12 місяців</td><td class="num">${money(r.expected_gross)}</td></tr></tbody></table><h3>Метод</h3><p>Ймовірність платежу × очікувана сума за умови платежу. Ознаки використовують лише події до дати зрізу, відомі на цю дату. Вимоги на правовій перевірці та з непідтвердженою повнотою історії не отримують прогнозу.</p><h3>Межі використання</h3><p>Результат демонструє роботу навчального процесу. Точність на українських реальних портфелях не перевірена. Договори без прогнозу не є встановленими неплатниками. 12-місячні надходження не дорівнюють загальним зборам за 36 місяців і не підставлені в оцінку ціни.</p><p>Для застосування: перенавчити модель на дозволеній історії, перевірити на пізніших портфелях, узгодити правові обмеження, витрати й часову структуру стягнення.</p><small>Sergey Golubev · NPL Investment Lab</small></article>`;
}
function exportPreScores(){
  const r=preState.result,keys=['loan_id','borrower_id','segment','as_of_date','horizon_end','status','probability','conditional','expected','unseen_seller'];
  const cell=v=>{if(v===null||v===undefined)return '';let s=String(v);if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};
  const lines=[['model_id','synthetic_training',...keys].join(','),...r.scores.map(s=>[r.model_id,r.synthetic_training,...keys.map(k=>s[k])].map(cell).join(','))];
  download('npl-project-forecast.csv','\uFEFF'+lines.join('\r\n'),'text/csv;charset=utf-8');toast('Поточний прогноз експортовано.');
}
document.addEventListener('click',e=>{
  const view=e.target.closest('[data-pre-view]');if(view){preState.view=view.dataset.preView;renderPrepurchase();}
  const loan=e.target.closest('[data-pre-loan]');if(loan)showPreLoan(loan.dataset.preLoan);
  const action=e.target.closest('[data-action]')?.dataset.action;
  if(action==='pre-export')exportPreScores();
  if(action==='pre-import')$('#pre-input').click();
  if(action==='pre-reset'){preState.case=preState.original;preState.result=PRE.scorePackage(preState.model,preState.case);preState.external=false;preState.search='';preState.filter='scored';error('');renderPrepurchase();}
});
document.addEventListener('input',e=>{if(e.target.id==='pre-search'){preState.search=e.target.value;renderPreRows();}});
document.addEventListener('change',async e=>{
  if(e.target.id==='pre-filter'){preState.filter=e.target.value;renderPreRows();}
  if(e.target.id!=='pre-input')return;
  const file=e.target.files[0];if(!file)return;
  try{if(file.size>20*1024*1024)throw Error('Ліміт JSON — 20 МБ.');const pack=JSON.parse(await file.text());const scored=PRE.scorePackage(preState.model,pack);preState.case=pack;preState.result=scored;preState.external=true;preState.view='forecast';preState.search='';preState.filter='scored';error('');renderPrepurchase();toast('Пакет оцінено локально базовою демонстраційною моделлю.');}catch(err){error('Пакет не завантажено: '+err.message);}finally{e.target.value='';}
});
